-- =====================================================================
-- 데모 규모 시드 (2/2): 작업 전 점검(TBM, 제38조 작업계획서), 사고
--
-- 작업 전 점검 41건(V10의 1건 포함 42): 완료, 승인, 조건부 승인(잠정조치), 승인 대기(오늘, 내일),
-- 작업 보류(사고 6 후속). 지게차 하역과 천장크레인 인양은 안전보건규칙 제38조 대상이라 서식 이름이
-- 작업계획서로 갈린다(WorkDocument.of가 작업명, 설비명으로 판단).
--
-- 사고 5건(V10의 1건 포함 6): 끼임 휴업 2일, 물체에 맞음 휴업 1일, 아차사고, 화재 휴업 6일(조사표 제출),
-- 천장크레인 물체에 맞음 휴업 14일(조사표 작성 필요, 수시평가 작성 중, 내일 인양 작업 보류).
-- =====================================================================

-- ── 작업 전 점검 ───────────────────────────────────────────────────
SELECT setval('work_plan_id_seq', 42, true);

-- ── 사고 ───────────────────────────────────────────────────────────
SELECT setval('incident_id_seq', 6, true);

-- 사고 6(천장크레인)의 수시평가는 아직 작성 중이다. 사고 직후 자동 생성분이라 참여자와 담당자가 비어 있다
UPDATE assessment SET inspector = NULL WHERE id = 24;
