  (2, 1, 7, 24, '지붕 배수구 낙엽 청소', '공장동 옥상', (CURRENT_DATE - 355), 3.0, '지붕 진입, 안전대 체결, 배수구 청소, 하강', '작업 전 TBM 실시, 이상 시 작업 중지', '작업: 지붕 배수구 낙엽 청소 / 공장동 옥상 / ' || (CURRENT_DATE - 355)::text || chr(10) || '작업자: 김철수 반장, 강태호' || chr(10) || '대상 설비: 지붕 작업 구역 (공장동 옥상)' || chr(10) || '' || chr(10) || '위험 포인트' || chr(10) || '1. 높이 6m 지붕 작업입니다. 떨어지면 크게 다칩니다' || chr(10) || '2. 채광창은 사람 무게를 버티지 못합니다' || chr(10) || '' || chr(10) || '지킬 것' || chr(10) || '1. 안전대를 구명줄에 걸고 작업합니다' || chr(10) || '2. 채광창 위로 올라서지 않습니다' || chr(10) || '3. 안전모, 안전대를 착용합니다' || chr(10) || '' || chr(10) || '위험하면 작업을 멈추고 관리감독자에게 알립니다.', (((CURRENT_DATE - 355) + TIME '08:10') AT TIME ZONE 'Asia/Seoul'), 'CLOSED', '잠정조치: 2인 1조, 용마루 임시 구명줄 설치 후 작업', '홍길동', (((CURRENT_DATE - 356) + TIME '16:40') AT TIME ZONE 'Asia/Seoul'), (((CURRENT_DATE - 355) + TIME '17:00') AT TIME ZONE 'Asia/Seoul'), NULL, (((CURRENT_DATE - 356) + TIME '14:20') AT TIME ZONE 'Asia/Seoul')),
  (3, 1, 5, 16, '제관 구조물 인양 (0.8톤)', '공장동 1층 제관구역', (CURRENT_DATE - 340), 2.0, '줄걸이 용구와 훅 해지장치 점검, 신호수 배치와 하부 통제선 설치, 인양, 착지 확인 후 줄걸이 해체', '작업 전 TBM 실시, 이상 시 작업 중지', '작업: 제관 구조물 인양 (0.8톤) / 공장동 1층 제관구역 / ' || (CURRENT_DATE - 340)::text || chr(10) || '작업자: 정민준 반장, 서하준, 한도윤' || chr(10) || '대상 설비: 천장크레인 1호 (공장동 1층 제관구역)' || chr(10) || '' || chr(10) || '위험 포인트' || chr(10) || '1. 인양물이 떨어지거나 흔들려 사람에 맞을 수 있습니다' || chr(10) || '2. 훅 해지장치나 슬링이 손상되면 줄걸이가 빠질 수 있습니다' || chr(10) || '3. 인양물 아래로 들어가면 피할 곳이 없습니다' || chr(10) || '' || chr(10) || '지킬 것' || chr(10) || '1. 줄걸이 용구와 훅 해지장치를 확인하고 인양합니다' || chr(10) || '2. 신호수 한 명이 신호하고 인양물 아래 출입을 막습니다' || chr(10) || '3. 안전모와 안전화를 착용합니다' || chr(10) || '' || chr(10) || '위험하면 작업을 멈추고 관리감독자에게 알립니다.', (((CURRENT_DATE - 340) + TIME '08:10') AT TIME ZONE 'Asia/Seoul'), 'CLOSED', NULL, '홍길동', (((CURRENT_DATE - 341) + TIME '16:40') AT TIME ZONE 'Asia/Seoul'), (((CURRENT_DATE - 340) + TIME '17:00') AT TIME ZONE 'Asia/Seoul'), NULL, (((CURRENT_DATE - 341) + TIME '14:20') AT TIME ZONE 'Asia/Seoul')),
